using System.Reflection;
using NetArchTest.Rules;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

public class LayerDependencyTests
{
    private static readonly Assembly Domain = typeof(Money).Assembly;
    private static readonly Assembly Application = typeof(AuthorizePayment).Assembly;
    private static readonly Assembly Infrastructure = typeof(HttpPaymentGateway).Assembly;

    // Technical detail: I/O, networking, serialization, persistence.
    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO", "System.Net", "System.Text.Json", "System.Data", "System.Xml",
        "System.Diagnostics.Process", "Microsoft.Data", "Microsoft.EntityFrameworkCore",
        "Microsoft.Extensions.Http", "Newtonsoft",
    ];

    [Fact]
    public void Domain_does_not_depend_on_Application_or_Infrastructure() =>
        AssertNoViolations(Types.InAssembly(Domain).ShouldNot()
            .HaveDependencyOnAny("PaymentAuthorization.Application", "PaymentAuthorization.Infrastructure"));

    [Fact]
    public void Application_does_not_depend_on_Infrastructure() =>
        AssertNoViolations(Types.InAssembly(Application).ShouldNot()
            .HaveDependencyOn("PaymentAuthorization.Infrastructure"));

    [Fact]
    public void Domain_does_not_use_technical_details() =>
        AssertNoViolations(Types.InAssembly(Domain).ShouldNot().HaveDependencyOnAny(TechnicalNamespaces));

    [Fact]
    public void Application_does_not_use_technical_details() =>
        AssertNoViolations(Types.InAssembly(Application).ShouldNot().HaveDependencyOnAny(TechnicalNamespaces));

    [Fact]
    public void Infrastructure_is_reachable_only_through_its_own_assembly() =>
        Assert.Empty(Domain.GetReferencedAssemblies().Concat(Application.GetReferencedAssemblies())
            .Where(a => a.Name == Infrastructure.GetName().Name));

    private static void AssertNoViolations(ConditionList rule)
    {
        var result = rule.GetResult();
        Assert.True(result.IsSuccessful, "Layer violation in: " + string.Join(", ", result.FailingTypeNames ?? []));
    }
}
